// Pictures and how-to text for the built-in exercises.
// Exercise data by RepDB (repdb.co) — free tier, attribution required.
// The JSON is generated by scripts/build-exercise-media.py; the images are
// loaded from RepDB's own site and are not stored in this repository.
import media from './exercise-media.json';

export type ExerciseMedia = {
  id: string;
  /** Image file names: start + peak pose, or one pose for holds. */
  frames: string[];
  description: string;
  steps: string[];
  tips: string[];
  /** Detailed muscles (RepDB names like "pectoralis_major"). */
  primary: string[];
  secondary: string[];
};

const ALL = media as Record<string, ExerciseMedia>;

const IMAGE_BASE = 'https://exercise-dataset.com/images/flat/';

export const REPDB_URL = 'https://repdb.co';

export function getMedia(exerciseName: string): ExerciseMedia | null {
  return ALL[exerciseName] ?? null;
}

export function imageUrl(frame: string): string {
  return IMAGE_BASE + frame;
}

/** YouTube search for a short form tutorial. Works for custom exercises too. */
export function formVideoUrl(exerciseName: string): string {
  const clean = exerciseName.replace(/[()]/g, ' ').replace(/\s+/g, ' ').trim();
  return `https://www.youtube.com/results?search_query=${encodeURIComponent(`${clean} proper form tutorial`)}`;
}
